function drawMapButterfly(parent,x,y,range,offset){
 const root=svgEl('g',{class:'map-butterfly',transform:`translate(${x.toFixed(2)} ${y.toFixed(2)})`,role:'button',tabindex:0},parent);
 root.style.setProperty('--fly-range',`${range.toFixed(2)}px`);
 root.style.setProperty('--flight-delay',`${-offset*.9}s`);
 const flight=svgEl('g',{class:'butterfly-flight'},root);
 const flutter=svgEl('g',{class:'butterfly-flutter'},flight);
 svgEl('path',{d:'M0 -1 Q-4.5 -8 -7.2 -5 Q-9 -1 -4.2 1.2 Q-7.4 6 -3 5.8 Q-1.1 5.4 0 1.2 Z',class:'butterfly-wing wing-left'},flutter);
 svgEl('path',{d:'M0 -1 Q4.5 -8 7.2 -5 Q9 -1 4.2 1.2 Q7.4 6 3 5.8 Q1.1 5.4 0 1.2 Z',class:'butterfly-wing wing-right'},flutter);
 svgEl('path',{d:'M0 -4 V4',class:'butterfly-body'},flutter);
 svgEl('path',{d:'M0 -3 Q-2 -8 -3 -8 M0 -3 Q2 -8 3 -8',class:'butterfly-antennae'},flutter);
 return root;
}
function drawLegislativeBud(parent,x,y,offset){
 const root=svgEl('g',{class:'map-legislation',transform:`translate(${x.toFixed(2)} ${y.toFixed(2)})`,role:'button',tabindex:0},parent);
 root.style.setProperty('--leaf-delay',`${-offset*.7}s`);
 const bud=svgEl('g',{class:'legislation-grow'},root);
 svgEl('path',{d:'M0 6 Q-1 0 0 -5',stroke:'#5c8063','stroke-width':1.6,fill:'none'},bud);
 svgEl('path',{d:'M0 0 Q-7 -7 -8 -1 Q-5 5 0 0 M0 -3 Q6 -10 8 -4 Q7 2 0 -3',fill:'#7a9b78',stroke:'#f1f4e6','stroke-width':.7},bud);
 return root;
}
function renderMapEvents(){
 const parent=$('mapEvents');if(!parent)return;parent.replaceChildren();
 const {finance,news,debates,legislation}=mapDataRecords();
 const configurations=[
  {key:'finance',records:$('layerFinance').checked?finance:[],className:'map-money',symbol:'♢',title:'Reported campaign finance',description:'A published filing or candidate-cycle aggregate, not a real-time transaction.',action:()=>switchView('finance')},
  {key:'news',records:$('layerNews').checked?news:[],className:'map-firefly',symbol:'✧',title:'Published political news',description:'Observed news coverage, not a representative public-opinion measurement.',action:()=>switchView('news')},
  {key:'debates',records:$('layerDebates').checked?debates:[],className:'map-butterfly',symbol:'🦋',title:'Documented debate',description:'A reported political debate. No winner is inferred.',action:()=>switchView('debates')},
  {key:'legislation',records:$('layerLegislation').checked?legislation:[],className:'map-legislation',symbol:'❧',title:'Legislative record',description:'Published government activity, not a measurement of support.',action:()=>switchView('issues')}
 ];
 for(const cfg of configurations){const perState=new Map();for(const record of cfg.records){
  const n=perState.get(record.state)||0;if(n>=4)continue;
  const flight=cfg.key==='debates'?safeButterflyFlight(record.state,n):null;
  if(cfg.key==='debates'&&!flight)continue; // Never draw a clipped or off-map butterfly.
  const position=flight?[flight.x,flight.y]:statePoint(record.state);if(!position)continue;perState.set(record.state,n+1);
  const [x,y]=position;
  const layer=stateLayer(parent,record.state);
  const node=cfg.key==='debates'?drawMapButterfly(layer,x,y,flight.range,n+perState.size):
   cfg.key==='legislation'?drawLegislativeBud(layer,x,y,n+perState.size):
   svgEl('text',{x,y,class:cfg.className,role:'button',tabindex:'0','text-anchor':'middle'},layer,cfg.symbol);
  node.setAttribute('aria-label',`${cfg.title} in ${stateName(record.state)}`);
  node.dataset.recordState=record.state;
  svgEl('title',{},node,`${cfg.title} · ${stateName(record.state)}`);
  activateMapNode(node,()=>showMapRecord(record.title||record.race||record.candidate||record.committee||cfg.title,`${cfg.description} Published ${fmt(record.published_at||record.reported_at||record.filing_date||record.date)}.`,record.source_url,cfg.title,cfg.action));
  addMapPeek(node,record.title||record.race||record.candidate||record.committee||cfg.title,`${stateName(record.state)} · ${cfg.title} · ${fmt(record.published_at||record.reported_at||record.filing_date||record.date)} · Click to inspect source`);
 }}
 const status=$('layerDataStatus');if(status)status.textContent=`MAP RECORDS · ${finance.length} finance · ${news.length} news · ${debates.length} debates · ${legislation.length} legislation. State-associated evidence is pinned within borders; national records remain available in their source views. Animated butterflies and budding leaves are decoration, not new events. Tiny states may omit moving butterflies to avoid clipping; all source records remain in their dedicated views.`;
}

function recordCard(p){return `<button class="record-card" data-poll="${esc(p.id)}"><span class="petal-icon">✿</span><span class="record-kicker">${esc(p.type||'Survey')} · ${p.state?esc(stateName(p.state)):'National'}</span><strong>${esc(p.subject||'Published observation')}</strong><span class="record-meta">${esc(p.pollster||p.source_name)} · ${fmt(p.published_at)}<br>${pollMetric(p)}</span></button>`}
// Import journal: each entry is emitted only by a real collector insert or revision.
// Publishing a snapshot or animating the meadow is not a new political event.
function formattedUTC(value){if(!value)return 'Not recorded';const d=new Date(value);return Number.isNaN(+d)?'Unknown':d.toLocaleString('en-US',{month:'short',day:'numeric',year:'numeric',hour:'numeric',minute:'2-digit',timeZone:'UTC',timeZoneName:'short'})}
function harvestEntries(){const found=new Map();for(const kind of ['polls','finance','legislation','news','debates'])for(const record of snapshot[kind]||[])if(record.id)found.set(kind+':'+record.id,record);
 return (Array.isArray(snapshot.harvest)?snapshot.harvest:[]).filter(entry=>entry&&entry.id&&entry.kind&&found.has(entry.kind+':'+entry.id)).slice().reverse().map(entry=>({...entry,record:found.get(entry.kind+':'+entry.id)}));}
function renderHarvest(){const all=harvestEntries(),filtered=all.filter(e=>harvestFilter==='all'||e.kind===harvestFilter);
 const summary=$('harvestSummary'),body=$('harvestRecords');if(!summary||!body)return;
 const fresh=all.filter(e=>{const age=Date.now()-Date.parse(e.collected_at||'');return Number.isFinite(age)&&age>=0&&age<48*3600*1000});
 const tags=[['polls','✿ Polls'],['legislation','❧ Bills'],['finance','◌ Finance'],['news','✧ Articles']];
 summary.innerHTML=`<span><b>${all.length}</b> recent import events retained</span><span><b>${fresh.length}</b> imported in the past 48h</span>${tags.map(([kind,label])=>`<span>${label} <b>${all.filter(e=>e.kind===kind).length}</b></span>`).join('')}<small>Up to 250 source-record changes are retained; counts are not nationwide totals or support measures.</small>`;
 body.innerHTML=filtered.length?filtered.slice(0,12).map(e=>{const r=e.record,title=r.subject||r.title||r.race||r.candidate||'Published record';const label={polls:'Survey',legislation:'Bill',finance:'Finance summary',news:'News item',debates:'Debate'}[e.kind]||'Record';const link=safeUrl(r.source_url||r.url);const place=r.state?stateName(r.state):'National';const published=r.published_at||r.date||r.filing_date||r.reported_at;
 return `<article class="harvest-entry"><span class="harvest-bloom" aria-hidden="true">${{polls:'✿',legislation:'❧',finance:'◌',news:'✧',debates:'🦋'}[e.kind]||'❀'}</span><div><div class="harvest-label">${esc(label)} · ${esc(e.change==='revised'?'Revised record':'First collected')} · ${esc(place)}</div><strong>${esc(title)}</strong><small>Collected ${esc(formattedUTC(e.collected_at))} · Source published ${fmt(published)} · ${esc(e.source_id||'Source unspecified')}</small>${e.kind==='polls'?`<button class="harvest-inspect" data-harvest-poll="${esc(r.id)}" type="button">Inspect poll details ↗</button>`:link!=='#'?`<a href="${link}" rel="noopener noreferrer" target="_blank">Open original source ↗</a>`:''}</div></article>`}).join(''):'<div class="harvest-empty">No new or revised records recorded in this journal for this selection. The existing garden data remains accessible; a successful API check by itself does not create new blooms.</div>';
 body.querySelectorAll('[data-harvest-poll]').forEach(b=>b.onclick=()=>showPoll((snapshot.polls||[]).find(r=>r.id===b.dataset.harvestPoll)));
 document.querySelectorAll('.harvest-filter').forEach(b=>{const selected=b.dataset.harvestKind===harvestFilter;b.classList.toggle('active',selected);b.setAttribute('aria-pressed',String(selected))});
}
function renderRecent(){let ps=visiblePolls().slice().sort((a,b)=>(b.published_at||'').localeCompare(a.published_at||''));$('recentCards').innerHTML=ps.length?ps.slice(0,3).map(recordCard).join(''):'<div class="empty-state">No verified recent polls available.</div>';document.querySelectorAll('#recentCards [data-poll]').forEach(b=>b.onclick=()=>showPoll(ps.find(p=>p.id===b.dataset.poll)))}
let parallelDiscovery=new Set();
function parallelRecords(code,topic){const cutoff=replayDate||new Date().toISOString().slice(0,10);const allow=r=>(r.state===code)&&(topic==='all'||r.topic===topic||(r.topics||[]).includes(topic))&&Boolean(r.published_at||r.reported_at||r.date||r.filing_date)&&String(r.published_at||r.reported_at||r.date||r.filing_date).slice(0,10)<=cutoff;return {polls:visiblePolls().filter(allow),finance:(snapshot.finance||[]).filter(allow),legislation:(snapshot.legislation||[]).filter(allow),debates:(snapshot.debates||[]).filter(allow),news:(snapshot.news||[]).filter(allow)}}
/** The meadow and grass are scenery. Only source-backed records receive data glyphs. */
